import { ModelAgent, ModelAgentSetupNotice } from '@/components/model-agent'

export default function ModelAgentPage() {
  const urn = process.env.APS_MODEL_URN
  if (!urn) {
    return (
      <main className="flex min-h-svh items-center justify-center p-6">
        <ModelAgentSetupNotice />
      </main>
    )
  }
  return <ModelAgent urn={urn} />
}

import { LoaderCircleIcon } from 'lucide-react'

export default function ModelAgentLoading() {
  return (
    <main className="flex min-h-svh flex-col items-center justify-center gap-3 bg-background p-6">
      <output className="flex items-center gap-2 text-muted-foreground text-sm">
        <span aria-hidden className="grid size-4 animate-spin place-items-center">
          <LoaderCircleIcon className="size-4" />
        </span>
        Loading canterafx
      </output>
    </main>
  )
}

'use client'

import { SparklesIcon, TriangleAlertIcon, XIcon } from 'lucide-react'
import {
  type RefObject,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
} from 'react'
import { APSViewer } from '@/components/ui/aps-viewer/aps-viewer'
import { useAPSViewerStore } from '@/components/ui/aps-viewer/context'
import {
  APSViewerSettings,
  type APSViewerSettingsValue,
  apsViewerPropsFor,
  DEFAULT_APS_VIEWER_SETTINGS,
  parseAPSViewerSettings,
} from '@/components/ui/aps-viewer/settings'
import type { ViewerStore } from '@/components/ui/aps-viewer/store'
import { Button } from '@/components/ui/button'
import { FxTerminal } from '@/components/ui/fx-terminal/fx-terminal'
import { Sheet, SheetClose, SheetContent, SheetTitle } from '@/components/ui/sheet'
import { statusInkClasses, statusToneClasses } from '@/components/ui/token-status'
import type { AgentRuntimeStatus } from '@/lib/agent-types'
import { cn } from '@/lib/utils'
import { type ColorLedger, createViewerAgentTools } from '@/lib/viewer-agent-tools'
import { AEC_STARTER_EXTENSIONS } from '@/lib/viewer-extension-types'
import type { GetAccessToken } from '@/lib/viewer-types'

export interface ModelAgentProps {
  /** Model Derivative URN (base64) of a translated model, with or without the `urn:` prefix. */
  urn: string
  viewerTokenEndpoint?: string
  gatewayBase?: string
  embedded?: boolean
  className?: string
}

const STARTER_VIEWER_SETTINGS: APSViewerSettingsValue = {
  ...DEFAULT_APS_VIEWER_SETTINGS,
  extensions: AEC_STARTER_EXTENSIONS.map((entry) => entry.id),
}
const VIEWER_SETTINGS_KEY = 'cantera:model-agent-page:viewer-settings'
const PANEL_WIDTH_KEY = 'cantera:model-agent-page:panel-width'
const COMPACT_QUERY = '(max-width: 767px)'
const DEFAULT_PANEL_WIDTH = 400
const MIN_PANEL_WIDTH = 360
const MAX_PANEL_RATIO = 0.6

// Each stored value falls back to an in-memory copy when the browser refuses
// storage (private windows, blocked site data), so choices last the visit.
function createStoredValue(key: string) {
  const listeners = new Set<() => void>()
  let unsaved: string | null = null
  return {
    read(): string | null {
      try {
        return window.localStorage.getItem(key)
      } catch {
        return unsaved
      }
    },
    write(raw: string | null): void {
      try {
        if (raw === null) window.localStorage.removeItem(key)
        else window.localStorage.setItem(key, raw)
      } catch {
        unsaved = raw
      }
      for (const listener of listeners) listener()
    },
    subscribe(listener: () => void): () => void {
      const onStorage = (event: StorageEvent) => {
        if (event.key === key) listener()
      }
      listeners.add(listener)
      window.addEventListener('storage', onStorage)
      return () => {
        listeners.delete(listener)
        window.removeEventListener('storage', onStorage)
      }
    },
  }
}

const storedViewerSettings = createStoredValue(VIEWER_SETTINGS_KEY)
const storedPanelWidth = createStoredValue(PANEL_WIDTH_KEY)

function usePersistedViewerSettings(): [
  APSViewerSettingsValue,
  (value: APSViewerSettingsValue) => void,
] {
  const raw = useSyncExternalStore(
    storedViewerSettings.subscribe,
    storedViewerSettings.read,
    () => null,
  )
  const settings = useMemo(() => {
    if (!raw) return STARTER_VIEWER_SETTINGS
    try {
      return parseAPSViewerSettings(JSON.parse(raw), STARTER_VIEWER_SETTINGS)
    } catch {
      return STARTER_VIEWER_SETTINGS
    }
  }, [raw])
  const write = useCallback((value: APSViewerSettingsValue) => {
    const next = JSON.stringify(value)
    storedViewerSettings.write(next === JSON.stringify(STARTER_VIEWER_SETTINGS) ? null : next)
  }, [])
  return [settings, write]
}

function usePersistedPanelWidth(): [number, (width: number) => void] {
  const raw = useSyncExternalStore(storedPanelWidth.subscribe, storedPanelWidth.read, () => null)
  const parsed = Number(raw)
  const width = raw && Number.isFinite(parsed) && parsed > 0 ? parsed : DEFAULT_PANEL_WIDTH
  const write = useCallback((next: number) => storedPanelWidth.write(String(Math.round(next))), [])
  return [width, write]
}

function subscribeCompact(onChange: () => void): () => void {
  const list = window.matchMedia(COMPACT_QUERY)
  list.addEventListener('change', onChange)
  return () => list.removeEventListener('change', onChange)
}

function useCompactLayout(): boolean {
  return useSyncExternalStore(
    subscribeCompact,
    () => window.matchMedia(COMPACT_QUERY).matches,
    () => false,
  )
}

/** Hands the viewer store, which lives inside APSViewer, to the tool catalog outside it. */
function createViewerSource() {
  let store: ViewerStore | null = null
  return {
    getViewer: () => store?.getViewer() ?? null,
    attach(next: ViewerStore): () => void {
      store = next
      return () => {
        if (store === next) store = null
      }
    },
  }
}

type ViewerSource = ReturnType<typeof createViewerSource>

function ViewerStoreBridge({ source }: { source: ViewerSource }) {
  const store = useAPSViewerStore()
  useEffect(() => source.attach(store), [source, store])
  return null
}

function ColorLegend({ colors, className }: { colors: ColorLedger; className?: string }) {
  const legend = useSyncExternalStore(colors.subscribe, colors.legend, colors.legend)
  if (legend.length === 0) return null
  return (
    <section
      aria-label="Agent colours"
      className={cn(
        'absolute z-10 grid min-w-48 max-w-64 gap-1.5 rounded-lg border border-border bg-background px-3 py-2.5 text-foreground text-xs shadow-sm',
        className,
      )}
    >
      <p className="text-muted-foreground uppercase tracking-wide">Agent colours</p>
      <ul className="grid gap-1.5">
        {legend.map((entry) => (
          <li
            key={`${entry.hex}-${entry.label}`}
            className="grid grid-cols-[0.75rem_minmax(0,1fr)_auto] items-center gap-2"
          >
            <span
              aria-hidden
              className="size-3 rounded-xs border border-border"
              style={{ background: entry.hex }}
            />
            <span className="truncate">{entry.label}</span>
            <span className="font-mono text-muted-foreground tabular-nums">{entry.count}</span>
          </li>
        ))}
      </ul>
    </section>
  )
}

function DockResizeHandle({
  label,
  width,
  onWidthChange,
  target,
}: {
  label: string
  width: number
  onWidthChange: (width: number) => void
  target: RefObject<HTMLElement | null>
}) {
  const drag = useRef<{ startX: number; startWidth: number } | null>(null)
  const clamp = (next: number) => {
    const container = target.current?.parentElement?.clientWidth ?? 0
    const max = container > 0 ? container * MAX_PANEL_RATIO : Number.POSITIVE_INFINITY
    onWidthChange(Math.max(MIN_PANEL_WIDTH, Math.min(next, max)))
  }
  const rendered = () => target.current?.getBoundingClientRect().width ?? width
  return (
    <button
      type="button"
      aria-label={label}
      className="group/resize absolute inset-y-0 -start-1.5 z-10 flex w-3 cursor-col-resize touch-none justify-center outline-none"
      onPointerDown={(event) => {
        if (event.button !== 0) return
        event.preventDefault()
        event.currentTarget.setPointerCapture(event.pointerId)
        drag.current = { startX: event.clientX, startWidth: rendered() }
      }}
      onPointerMove={(event) => {
        if (drag.current) clamp(drag.current.startWidth + drag.current.startX - event.clientX)
      }}
      onPointerUp={(event) => {
        drag.current = null
        event.currentTarget.releasePointerCapture(event.pointerId)
      }}
      onPointerCancel={() => {
        drag.current = null
      }}
      onKeyDown={(event) => {
        const step = event.shiftKey ? 64 : 16
        if (event.key === 'ArrowLeft') clamp(rendered() + step)
        else if (event.key === 'ArrowRight') clamp(rendered() - step)
        else return
        event.preventDefault()
      }}
    >
      <span
        aria-hidden
        className="h-full w-0.5 bg-transparent group-hover/resize:bg-border group-focus-visible/resize:w-1 group-focus-visible/resize:bg-ring"
      />
    </button>
  )
}

function ModelAgentSetupNotice({ className }: { className?: string }) {
  return (
    <div
      role="status"
      data-slot="model-agent-setup"
      className={cn('flex max-w-md flex-col items-center gap-3 text-center', className)}
    >
      <span
        className={cn('grid size-10 place-items-center rounded-full', statusToneClasses.warning)}
      >
        <TriangleAlertIcon aria-hidden className="size-5" />
      </span>
      <h2 className="font-heading font-medium text-xl">Choose a model for the agent</h2>
      <p className="text-pretty text-muted-foreground text-sm">
        Set APS_MODEL_URN to the base64 URN of a model Autodesk has already translated, along with
        APS_CLIENT_ID, APS_CLIENT_SECRET, and AI_GATEWAY_API_KEY, then reload.
      </p>
    </div>
  )
}

function ModelAgent({
  urn,
  viewerTokenEndpoint = '/api/viewer-token',
  gatewayBase = '/api/agent/gateway',
  embedded = false,
  className,
}: ModelAgentProps) {
  const compact = useCompactLayout()
  const [dockOpen, setDockOpen] = useState(true)
  const [sheetOpen, setSheetOpen] = useState(false)
  const [viewerError, setViewerError] = useState<string | null>(null)
  const [terminalReady, setTerminalReady] = useState(false)
  const [viewerSettings, setViewerSettings] = usePersistedViewerSettings()
  const [panelWidth, setPanelWidth] = usePersistedPanelWidth()
  const [viewerSource] = useState(createViewerSource)
  const [tools] = useState(() => createViewerAgentTools(viewerSource.getViewer))
  const dockRef = useRef<HTMLElement>(null)

  useEffect(() => () => tools.dispose(), [tools])

  const getAccessToken = useCallback<GetAccessToken>(async () => {
    const response = await fetch(viewerTokenEndpoint, { cache: 'no-store' })
    if (!response.ok) throw new Error('The viewer token is unavailable.')
    return (await response.json()) as Awaited<ReturnType<GetAccessToken>>
  }, [viewerTokenEndpoint])

  const open = compact ? sheetOpen : dockOpen
  const setOpen = (next: boolean) => {
    if (!next) setTerminalReady(false)
    if (compact) setSheetOpen(next)
    else setDockOpen(next)
  }

  const runtimeStatus: AgentRuntimeStatus = terminalReady ? 'ready' : 'starting'

  const terminal = (
    <FxTerminal
      tools={tools}
      gatewayBase={gatewayBase}
      colorScheme="dark"
      onReady={() => setTerminalReady(true)}
      className="min-h-0 flex-1"
    />
  )

  const Root = embedded ? 'div' : 'main'

  return (
    <Root
      data-slot="model-agent"
      className={cn(
        'flex h-svh min-h-[32rem] w-full min-w-0 flex-col overflow-hidden bg-background text-foreground',
        embedded && 'relative',
        className,
      )}
    >
      <header className="flex h-14 shrink-0 items-center gap-2 border-border border-b ps-4 pe-2 sm:gap-3">
        <h1 className="min-w-0 flex-1 truncate font-medium font-mono text-sm lowercase">
          canterafx
        </h1>
        <Button
          type="button"
          variant={open ? 'default' : 'outline'}
          aria-pressed={open}
          className="h-11 min-w-11 gap-2 px-3 max-sm:px-0"
          onClick={() => setOpen(!open)}
        >
          <SparklesIcon aria-hidden />
          <span className="max-sm:sr-only">Agent</span>
        </Button>
      </header>

      <div className="flex min-h-0 flex-1">
        <section aria-label="Model viewer" className="relative min-h-0 min-w-0 flex-1 bg-muted">
          <APSViewer
            urn={urn}
            getAccessToken={getAccessToken}
            profile="aec"
            {...apsViewerPropsFor(viewerSettings)}
            className="size-full"
            onModelLoaded={() => setViewerError(null)}
            onError={(error) => setViewerError(error.message)}
          >
            <ViewerStoreBridge source={viewerSource} />
            <APSViewerSettings
              value={viewerSettings}
              onValueChange={setViewerSettings}
              resetValue={STARTER_VIEWER_SETTINGS}
            />
            <ColorLegend colors={tools.colors} className="top-3 left-3" />
          </APSViewer>
          {viewerError && (
            <div
              role="alert"
              className="absolute inset-x-3 top-3 z-20 mx-auto flex max-w-md items-start gap-3 rounded-lg border border-border bg-background p-3 shadow-sm"
            >
              <TriangleAlertIcon
                aria-hidden
                className={cn('mt-0.5 size-4 shrink-0', statusInkClasses.danger)}
              />
              <div className="flex min-w-0 flex-col gap-0.5">
                <p className="font-medium text-sm">The model could not load</p>
                <p className="break-words text-muted-foreground text-xs">{viewerError}</p>
              </div>
            </div>
          )}
        </section>

        <div className="contents" data-agent-runtime-status={runtimeStatus}>
          {compact ? (
            <Sheet open={open} onOpenChange={setOpen}>
              <SheetContent
                side="bottom"
                showCloseButton={false}
                className="gap-0 rounded-t-2xl p-0 data-[side=bottom]:h-[min(85dvh,44rem)]"
              >
                <div className="flex h-12 shrink-0 items-center justify-between ps-4 pe-1">
                  <SheetTitle className="text-sm">Agent</SheetTitle>
                  <SheetClose
                    render={
                      <Button
                        variant="ghost"
                        size="icon"
                        className="size-11"
                        aria-label="Close agent"
                      />
                    }
                  >
                    <XIcon aria-hidden />
                  </SheetClose>
                </div>
                {terminal}
              </SheetContent>
            </Sheet>
          ) : (
            open && (
              <aside
                ref={dockRef}
                aria-label="Agent"
                style={{
                  width: panelWidth,
                  minWidth: MIN_PANEL_WIDTH,
                  maxWidth: `${MAX_PANEL_RATIO * 100}%`,
                }}
                className="relative flex h-full shrink-0 flex-col border-border border-s bg-background"
              >
                <DockResizeHandle
                  label="Resize agent panel"
                  width={panelWidth}
                  onWidthChange={setPanelWidth}
                  target={dockRef}
                />
                {terminal}
              </aside>
            )
          )}
        </div>
      </div>
    </Root>
  )
}

export { ModelAgent, ModelAgentSetupNotice }

import { APS_BASE_URL, type TokenSource } from 'aec-auth'
import { apsOAuth, memoryVaultStore, vaultTokenSource } from 'aec-auth/vault'
import { connection } from 'next/server'

const VIEWER_SCOPES = ['viewables:read'] as const
const tokenSources = new Map<string, TokenSource>()

// Vercel sets VERCEL_PROJECT_PRODUCTION_URL on every deployment, so a one-click
// deploy has a trusted origin before its owner knows the URL.
function deploymentOrigin(): string | undefined {
  if (process.env.APP_ORIGIN) return process.env.APP_ORIGIN
  const vercel = process.env.VERCEL_PROJECT_PRODUCTION_URL
  return vercel ? `https://${vercel}` : undefined
}

function apiBase(origin: string): string {
  const configured = process.env.APS_AUTH_BASE_URL
  if (!configured) return APS_BASE_URL
  if (!configured.startsWith('/')) return configured
  const trusted = deploymentOrigin()
  if (!trusted && process.env.NODE_ENV === 'production') {
    throw new Error('APP_ORIGIN is required with a relative APS_AUTH_BASE_URL in production')
  }
  return `${trusted ? new URL(trusted).origin : origin}${configured}`
}

function getViewerTokenSource(base: string): TokenSource {
  const existing = tokenSources.get(base)
  if (existing) return existing
  const clientId = process.env.APS_CLIENT_ID
  const clientSecret = process.env.APS_CLIENT_SECRET
  if (!clientId || !clientSecret) throw new Error('APS viewer credentials are not configured')
  const source = vaultTokenSource({
    store: memoryVaultStore(),
    providers: {
      aps: apsOAuth({ clientId, clientSecret, baseUrl: base === APS_BASE_URL ? undefined : base }),
    },
  })
  tokenSources.set(base, source)
  return source
}

/** A 2-legged viewer token with the minimum Model Derivative read scope. */
export async function GET(request: Request): Promise<Response> {
  await connection()
  try {
    const base = apiBase(new URL(request.url).origin)
    const token = await getViewerTokenSource(base).getToken({
      provider: 'aps',
      subject: { type: 'app' },
      scopes: VIEWER_SCOPES,
      forceRefresh: true,
    })
    return Response.json(
      {
        accessToken: token.token,
        expiresInSeconds: Math.max(1, Math.floor((token.expiresAt - Date.now()) / 1000)),
      },
      { headers: { 'Cache-Control': 'no-store' } },
    )
  } catch (error) {
    console.error('Viewer token request failed', error)
    return Response.json(
      { error: 'The viewer token is unavailable.' },
      { status: 503, headers: { 'Cache-Control': 'no-store' } },
    )
  }
}

const GATEWAY_ORIGIN = 'https://ai-gateway.vercel.sh'
const ALLOWED_ROUTES = new Map([
  ['/coding-agent/v1/models', 'GET'],
  ['/v4/ai/language-model', 'POST'],
])
const ALLOWED_MODEL = 'anthropic/claude-haiku-5.5'
const CATALOG_PATH = '/coding-agent/v1/models'
const CATALOG_TTL_MS = 10 * 60_000
const SESSION_HEADERS = ['x-session-affinity', 'x-session-id']
const SESSION_VALUE = /^[A-Za-z0-9_.:-]{1,128}$/
const MAX_BODY_BYTES = 1_048_576
const UPSTREAM_TIMEOUT_MS = 120_000
const RATE_LIMIT = 60
const RATE_WINDOW_MS = 60_000
const RESPONSE_HEADERS = [
  'content-type',
  'x-vercel-id',
  'x-generation-id',
  'x-model-id',
  'x-vercel-ai-gateway-provider',
]

export type GatewayErrorType =
  | 'not-found'
  | 'not-configured'
  | 'rate-limited'
  | 'too-large'
  | 'invalid-request'
  | 'model-not-allowed'
  | 'upstream-error'

const buckets = new Map<string, { count: number; resetAt: number }>()

interface CachedCatalog {
  body: ArrayBuffer
  contentType: string
  expiresAt: number
}

let catalog: CachedCatalog | null = null
let catalogRequest: Promise<CachedCatalog | null> | null = null

function catalogResponse(cached: CachedCatalog): Response {
  return new Response(cached.body.slice(0), {
    status: 200,
    headers: { 'content-type': cached.contentType, 'cache-control': 'no-store' },
  })
}

async function fetchCatalog(headers: Headers, signal: AbortSignal): Promise<CachedCatalog | null> {
  const upstream = await fetch(`${GATEWAY_ORIGIN}${CATALOG_PATH}`, {
    headers,
    redirect: 'error',
    signal,
  })
  if (!upstream.ok) {
    await upstream.body?.cancel()
    return null
  }
  return {
    body: await upstream.arrayBuffer(),
    contentType: upstream.headers.get('content-type') ?? 'application/json',
    expiresAt: Date.now() + CATALOG_TTL_MS,
  }
}

function rateLimited(ip: string): boolean {
  const now = Date.now()
  if (buckets.size > 10_000) {
    for (const [key, bucket] of buckets) if (bucket.resetAt < now) buckets.delete(key)
  }
  const bucket = buckets.get(ip)
  if (!bucket || bucket.resetAt < now) {
    buckets.set(ip, { count: 1, resetAt: now + RATE_WINDOW_MS })
    return false
  }
  bucket.count += 1
  return bucket.count > RATE_LIMIT
}

function clientIp(headers: Headers): string {
  return (
    headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
    headers.get('x-real-ip')?.trim() ||
    'local'
  )
}

function gatewayError(status: number, type: GatewayErrorType, message: string): Response {
  return Response.json(
    { error: { type, message } },
    { status, headers: { 'cache-control': 'no-store' } },
  )
}

async function readBody(request: Request): Promise<Uint8Array<ArrayBuffer> | null> {
  const declared = Number(request.headers.get('content-length') ?? 0)
  if (declared > MAX_BODY_BYTES) return null
  if (!request.body) return new Uint8Array()
  const reader = request.body.getReader()
  const chunks: Uint8Array[] = []
  let size = 0
  for (;;) {
    const { done, value } = await reader.read()
    if (done) break
    size += value.byteLength
    if (size > MAX_BODY_BYTES) {
      await reader.cancel()
      return null
    }
    chunks.push(value)
  }
  const body = new Uint8Array(size)
  let offset = 0
  for (const chunk of chunks) {
    body.set(chunk, offset)
    offset += chunk.byteLength
  }
  return body
}

function requestedModel(body: Uint8Array): string | null | undefined {
  try {
    const parsed: unknown = JSON.parse(new TextDecoder().decode(body))
    if (!parsed || typeof parsed !== 'object') return undefined
    const model = (parsed as { model?: unknown }).model
    if (model === undefined) return null
    return typeof model === 'string' ? model : undefined
  } catch {
    return undefined
  }
}

async function handle(
  request: Request,
  context: { params: Promise<{ path: string[] }> },
): Promise<Response> {
  const { path } = await context.params
  const pathname = `/${path.join('/')}`
  if (ALLOWED_ROUTES.get(pathname) !== request.method || new URL(request.url).search) {
    return gatewayError(404, 'not-found', 'This model endpoint is not available.')
  }
  const key = process.env.AI_GATEWAY_API_KEY
  if (!key) {
    return gatewayError(503, 'not-configured', 'The AI agent is not configured on this server.')
  }
  if (request.method === 'GET' && catalog && catalog.expiresAt > Date.now()) {
    return catalogResponse(catalog)
  }
  if (rateLimited(clientIp(request.headers))) {
    return gatewayError(429, 'rate-limited', 'Too many requests. Wait a minute and try again.')
  }

  let body: Uint8Array<ArrayBuffer> | undefined
  if (request.method === 'POST') {
    const raw = await readBody(request)
    if (!raw) {
      return gatewayError(413, 'too-large', 'This conversation is too long. Start a new one.')
    }
    const headerModel = request.headers.get('ai-language-model-id')
    const bodyModel = requestedModel(raw)
    if (bodyModel === undefined) {
      return gatewayError(400, 'invalid-request', 'The model request is not valid JSON.')
    }
    const models = [headerModel, bodyModel].filter((model) => model !== null)
    if (models.length === 0 || models.some((model) => model !== ALLOWED_MODEL)) {
      return gatewayError(
        400,
        'model-not-allowed',
        `Only ${ALLOWED_MODEL} is available through this server.`,
      )
    }
    body = raw
  }

  const headers = new Headers()
  for (const [name, value] of request.headers) {
    if (name.startsWith('ai-') || name === 'content-type' || name === 'accept') {
      headers.set(name, value)
    }
  }
  for (const name of SESSION_HEADERS) {
    const value = request.headers.get(name)
    if (value && SESSION_VALUE.test(value)) headers.set(name, value)
  }
  headers.set('authorization', `Bearer ${key}`)
  const signal = AbortSignal.any([request.signal, AbortSignal.timeout(UPSTREAM_TIMEOUT_MS)])

  if (pathname === CATALOG_PATH) {
    try {
      catalogRequest ??= fetchCatalog(headers, AbortSignal.timeout(UPSTREAM_TIMEOUT_MS)).finally(
        () => {
          catalogRequest = null
        },
      )
      const fresh = await catalogRequest
      if (fresh) {
        catalog = fresh
        return catalogResponse(fresh)
      }
    } catch (error) {
      console.error('AI Gateway model catalog request failed', error)
    }
    return gatewayError(502, 'upstream-error', 'The model service did not respond. Try again.')
  }

  try {
    const upstream = await fetch(`${GATEWAY_ORIGIN}${pathname}`, {
      method: request.method,
      headers,
      body,
      redirect: 'error',
      signal,
    })
    const out = new Headers({ 'cache-control': 'no-store' })
    for (const name of RESPONSE_HEADERS) {
      const value = upstream.headers.get(name)
      if (value) out.set(name, value)
    }
    return new Response(upstream.body, { status: upstream.status, headers: out })
  } catch (error) {
    if (request.signal.aborted) return new Response(null, { status: 499 })
    console.error('AI Gateway request failed', error)
    return gatewayError(502, 'upstream-error', 'The model service did not respond. Try again.')
  }
}

